    "shortDescription": "Viernes | 5:30 p. m. ¿Te apasionan las buenas historias y buscas un lugar donde compartirlas? Te invitamos a ser parte de este nuevo club...",
    "longDescription": "Viernes | 5:30 p. m. ¿Te apasionan las buenas historias y buscas un lugar donde compartirlas? Te invitamos a ser parte de este nuevo club de lectura, un espacio pensado exclusivamente para mentes inquietas entre los 15 y 24 años. Este es un punto de encuentro para descubrir otros mundos, debatir, asombrarnos y conocer a personas que comparten tu misma pasión por los libros. Para inaugurar nuestro camino de lectura, cruzaremos la puerta hacia lo desconocido y nos sumergiremos en el universo del maestro del suspenso: Stephen King. Juntos exploraremos sus misterios, la profunda psicología de sus personajes y esos giros narrativos que nos dejan sin aliento.",
