    "shortDescription": "Proyección de película. Cartelera. Dirigida por Fernando Eimbcke, 2026, México, 99 min. Idioma original. Recomendada para mayores de 7 añ...",
    "longDescription": "Proyección de película. Cartelera. Dirigida por Fernando Eimbcke, 2026, México, 99 min. Idioma original. Recomendada para mayores de 7 años. Olga lleva una vida estrictamente controlada, sin amigos ni relaciones, en un enorme bloque de pisos. Cuando, por necesidad económica, se ve obligada a alquilar una habitación, un hombre se muda al piso y, además, introduce a escondidas a su hijo de nueve años. Para su propia sorpresa, Olga comienza a forjar un vínculo inesperado con el niño. Su mundo cuidadosamente controlado empieza a tambalearse y, en contra de su voluntad, estas tres vidas comienzan a entrelazarse.",
