    "title": "Lanzamiento del libro Maestros Involuntarios por: Adrián Mastronardi",
    "shortDescription": "El próximo martes 25 de agosto lanzamos Maestros involuntarios , el libro de Adrian Mastronardi. Más de treinta años en tecnología latino...",
    "longDescription": "El próximo martes 25 de agosto lanzamos Maestros involuntarios , el libro de Adrian Mastronardi. Más de treinta años en tecnología latinoamericana (Globant, OLX, RappiPay, Delivery Hero, Habi) y unlibro que no habla de métricas sino de lo otro: la incertidumbre, la soledad del líder, el ego, el fracaso, ellegado. Cada capítulo parte de un verso, de Cavafi s a Pizarnik, y lo lleva al ofi cio de construir unaempresa. Prólogo de Simón Borrero, cofundador y CEO de Rappi. Esa noche será una conversación entre Adrian, Ricardo Sierra (CEO de Celsia) y Esteban Betancur(fundador y CEO de Prestigio). Al cierre, venta de ejemplares y fi rma con el autor.",
