    "shortDescription": "¿Te gusta crear en el momento y dejarte llevar por la imaginación? Exploraremos los principios de la improvisación: escucha, aceptación, ...",
    "longDescription": "¿Te gusta crear en el momento y dejarte llevar por la imaginación? Exploraremos los principios de la improvisación: escucha, aceptación, juego y creatividad. A través de ejercicios prácticos y dinámicos, aprenderás a reaccionar, construir ideas en grupo y confiar en tu intuición. Un espacio para reír, experimentar y soltar el miedo al error. ¡Inscríbete y ven a improvisar!",
