    "longDescription": "Proyección de película. Cartelera. Dirigida por Diana Ojeda, 2026, Colombia, 90 min. Idioma original. Recomendada para mayores de 12 años. En el cemento del estadio de Bucaramanga, el fervor popular es un territorio celosamente guardado por hombres. Durante una década, un colectivo de mujeres ha entregado su aliento a las graderías, pero las leyes no escritas del barrismo tradicional les prohíben constituirse de forma oficial y ondear su propia bandera. Guiadas por la determinación de Natalia, estas mujeres deciden rebelarse contra la marginación del sistema futbolístico. No obstante, disputar un espacio en un universo hostil acarrea consecuencias dolorosas. Mientras el colectivo resiste el acoso y la violencia en las calles, Natalia debe librar una batalla silenciosa en los tribunales familiares, donde su militancia política la coloca ante la inminente pérdida de la custodia de su hija. Esta obra constituye un viaje de sororidad que revela los verdaderos límites del \"aguante\" femenino cuando las luces de la cancha se apagan.",
    "startDate": "2026-08-27",
    "startTime": "17:00",
    "endTime": "21:00",
