    "shortDescription": "El Gran Salón y Comfama presentan una edición especial dedicada a la salsa que transformó la historia cultural de América Latina. Cabaret...",
    "longDescription": "El Gran Salón y Comfama presentan una edición especial dedicada a la salsa que transformó la historia cultural de América Latina. Cabaret literario Salsa & Son es una experiencia escénica que combina música en vivo, conversación, baile y narración para recorrer las historias que dieron origen a uno de los movimientos musicales más importantes de nuestro continente. Durante 90 minutos, el público vivirá un espectáculo que conecta emociones, recuerdos y celebración colectiva a través de canciones emblemáticas, relatos históricos y reflexiones sobre la identidad latinoamericana. Esta conversación bailable con Leonardo Padura y Fredy Ginebra es un encuentro entre la música y la memoria para viajar desde el Patio Teatro del Claustro Comfama.",
