    "id": "comfama-78700",
    "slug": "comfama-juego-vida3",
    "title": "Película: El juego de la vida",
    "shortDescription": "Proyección de película. Cartelera. Dirigida por Mario Andrés Ruiz Zuluaga, 2026, Colombia, 95 min. Idioma original. Apta para todo públic...",
    "longDescription": "Proyección de película. Cartelera. Dirigida por Mario Andrés Ruiz Zuluaga, 2026, Colombia, 95 min. Idioma original. Apta para todo público. Un documentalista sigue durante 14 años a cinco familias colombianas que luchan por avanzar en un país donde moverse no siempre significa progresar. En este tablero desigual, algunos nacen con comodines, otros con cartas marcadas. El documental explora cómo el punto de partida puede condicionar el destino, pero no determinarlo. Con una mirada íntima, revela las decisiones, frustraciones, resiliencias y pequeñas victorias de quienes apuestan por cambiar su camino, aún cuando las reglas no son iguales para todos. Frente a una estructura que premia a unos y castiga a otros, estas familias se convierten en espejo de un país donde la movilidad social es el verdadero juego. ¿Qué pasa cuando el azar reparte mal, pero la voluntad de jugar permanece intacta? EL JUEGO DE LA VIDA es una historia de lucha, dignidad y esperanza, narrada desde el corazón de Colombia.",
