    "longDescription": "Proyección de película. Cartelera. Título original: La petite derniere. Dirigida por Hafsia Herzi, 2025. Francia, Alemania, 106 min. Subtitulada. Apta para mayores de 15 años. Fátima, de 17 años, es la pequeña de tres hermanas. Vive en los suburbios, en una familia franco-argelina feliz y amorosa. Buena estudiante, ingresa en la Universidad de París. Al comenzar su vida como mujer adulta, se emancipa de su familia y sus tradiciones. Sale con alguien, hace amigos y explora un mundo completamente nuevo, mientras se enfrenta a un dilema desgarrador: ¿Cómo mantenerse fiel a una misma cuando reconciliar diferentes aspectos de la propia identidad parece imposible?",
