    "shortDescription": "Por: Roja Espiral. Recorreremos las historias que habitan en los hilos: relatos de cuidado, vida y memoria que nos han acompañado. Este e...",
    "longDescription": "Por: Roja Espiral. Recorreremos las historias que habitan en los hilos: relatos de cuidado, vida y memoria que nos han acompañado. Este espacio será una invitación a reconocer lo perdido, lo compartido y aquello que hoy nos invita a detenernos y escuchar. Mediante el bordado, abriremos una pausa para volver al tiempo lento, a la conversación y a las voces de lo cotidiano que se expresan a través de las manos y las artes textiles. En este taller aprenderemos la técnica de bordado en punto de cruz para crear un cuadro bordado, mientras enlazamos recuerdos y conversamos sobre las personas, oficios y saberes textiles que han tejido parte de nuestra historia.",
